CREATE SCHEMA app;
CREATE TYPE app.user_status AS ENUM ('active', 'on-hold', 'closed');
CREATE DOMAIN app.email AS text CHECK (VALUE LIKE '%@%');
CREATE TYPE app.address AS (street text, zip varchar(10));
CREATE TABLE app.users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email app.email NOT NULL UNIQUE,
  status app.user_status NOT NULL,
  manager_id bigint REFERENCES app.users (id),
  balance numeric(12, 2) NOT NULL DEFAULT 0,
  tags text[] NOT NULL DEFAULT '{}',
  home app.address,
  -- @go.type example.com/e2e/doc.Profile
  profile jsonb
);
CREATE TABLE app.orders (
  id bigint PRIMARY KEY,
  user_id bigint NOT NULL REFERENCES app.users (id),
  total numeric(12, 2) NOT NULL
);
CREATE TABLE app.tags (
  id int PRIMARY KEY,
  label text NOT NULL,
  kind text NOT NULL DEFAULT 'topic' CHECK (kind IN ('topic', 'brand'))
);
-- PostgreSQL computes both id and name_lower: neither is written.
CREATE TABLE app.nodes (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  parent bigint,
  name text NOT NULL,
  name_lower text NOT NULL GENERATED ALWAYS AS (lower(name)) STORED,
  size bigint NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX nodes_name ON app.nodes (name_lower);
